package com.agrolink.controller;import com.agrolink.dto.category.*;import com.agrolink.service.CategoryService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/categories") public class CategoryController{private final CategoryService s;public CategoryController(CategoryService s){this.s=s;}@GetMapping public List<CategoryResponse> all(){return s.all();}@PostMapping @PreAuthorize("hasRole('ADMIN')") public CategoryResponse create(@Valid @RequestBody CategoryRequest r){return s.create(r);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public CategoryResponse update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return s.update(id,r);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public void delete(@PathVariable Long id){s.delete(id);}}
